MATCH (x:PlantItem:PlateHeatExchanger {unit_id: '36'})
RETURN x.tag AS tag
ORDER BY tag;

MATCH (target:PlantItem {tag: 'V-3901'})-[:line_to]-(v:Valve)<-[:control]-(act:PlantItem)<-[:send_signal_to*1..]-(loop:ProcessControlFunction)
RETURN DISTINCT loop.loop_tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'EJ-401B'}), (b:PlantItem {tag: 'EJ-402A'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((x)-[:line_to]->(y) WHERE y.tag <> 'E-403'){1,} (b)
       } AS reachable

MATCH (:PlantItem {tag: 'P-4601'})-[:is_drawn_on]->(s:Sheet)
RETURN DISTINCT s.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (a:PlantItem {tag: 'M-4201'}), (b:PlantItem {tag: 'V-4201'}), (v:Valve)
WHERE v <> a AND v <> b
  AND EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (item:PlantItem {tag: 'T-4001'})-[:is_drawn_on]->(s:Sheet)
RETURN DISTINCT s.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (a:PlantItem {tag: 'H-4301'}), (b:PlantItem {tag: 'E-4301'})
RETURN a.tag AS source, b.tag AS destination,
       EXISTS {
         MATCH (a) ((x)-[:line_to]->(y) WHERE y.tag <> 'R-4301')+ (b)
       } AS can_flow_without_R-4301

MATCH (a:PlantItem {tag: 'P-4601'}), (b:PlantItem {tag: 'TK-4602'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'H-4301'}), (b:PlantItem {tag: 'E-4301'})
RETURN a.tag AS source, b.tag AS destination,
       EXISTS {
         MATCH (a) ((x)-[:line_to]->(y) WHERE y.tag <> 'R-4301')+ (b)
       } AS can_flow_without_R_4301

MATCH (v:GateValve {unit_id: '31'})
RETURN v.tag AS tag
ORDER BY tag;

MATCH (h:PlantItem {tag: 'H-3701'})-[:line_to]-(v:Valve)<-[:control]-(a:PlantItem)<-[:send_signal_to*1..]-(loop:ProcessControlFunction)
RETURN DISTINCT loop.loop_tag AS tag
ORDER BY tag;

MATCH (t:PlantItem:Tank {tag: 'T-3301'})-[:line_to]-(v:PlantItem:Valve)<-[:control]-(a:PlantItem)<-[:send_signal_to*1..]-(c:PlantItem:ProcessControlFunction)
RETURN DISTINCT c.loop_tag AS tag
ORDER BY tag;

MATCH (item:PlantItem {tag: 'EA-3001'})-[:is_drawn_on]->(sheet:Sheet)
RETURN DISTINCT sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (a:PlantItem {tag: 'P-3701C'}), (b:PlantItem {tag: 'E-3901'}), (v:PlantItem:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN count(DISTINCT v) AS valve_count

MATCH (:PlantItem {tag: 'EA-4401'})-[:is_drawn_on]->(s:Sheet)
RETURN DISTINCT s.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (v:PlantItem:PressureVessel {unit_id: '4'})
RETURN v.tag AS tag
ORDER BY tag;

MATCH (d:PlantItem {tag: 'D-501'})-[:line_to]-(v:Valve)<-[:control]-(a:PlantItem {kind: 'actuator'})<-[:send_signal_to*1..]-(loop:ProcessControlFunction)
RETURN DISTINCT loop.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'P-4501C'}), (b:PlantItem {tag: 'E-4701'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'TK-1004'}), (b:PlantItem {tag: 'P-1101B'}), (c:PlantItem {tag: 'P-1001A'})
RETURN a.tag AS source, b.tag AS destination,
       EXISTS {
         MATCH (a) ((x:PlantItem WHERE x <> c)-[:line_to]->(y:PlantItem WHERE y <> c))+ (b)
       } AS can_flow_without_intermediate

MATCH (a:PlantItem {tag: 'E-3301'}), (b:PlantItem {tag: 'P-3401C'})
RETURN EXISTS {
  MATCH (a) ((x:PlantItem WHERE x.tag <> 'YV-34001')-[:line_to]->(y:PlantItem WHERE y.tag <> 'YV-34001'))+ (b)
} AS can_flow_without_YV_34001

MATCH (a:PlantItem {tag: 'P-4201A'}), (b:PlantItem {tag: 'TK-4602'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'T-2101'}), (b:PlantItem {tag: 'T-2701'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem) WHERE x.tag <> 'E-2102' AND y.tag <> 'E-2102')+ (b)
       } AS reachable

MATCH (a:PlantItem {tag: 'EA-501'}), (b:PlantItem {tag: 'P-601B'})
MATCH (v:PlantItem:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN count(DISTINCT v.tag) AS valve_count

MATCH (a:PlantItem {tag: 'R-3701'}), (b:PlantItem {tag: 'T-4401'}), (v:PlantItem:Valve)
WHERE v <> a AND v <> b
  AND EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
WITH DISTINCT v
RETURN count(*) AS valve_count

MATCH (a:PlantItem {tag: 'P-701B'}), (b:PlantItem {tag: 'V-1101'})
WHERE EXISTS {
  MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem) WHERE x.tag <> 'YV-8012' AND y.tag <> 'YV-8012')+ (b)
}
RETURN b.tag AS tag veg

MATCH (a:PlantItem {tag: 'P-701B'}), (b:PlantItem {tag: 'V-1101'})
WHERE EXISTS {
  MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem) WHERE x.tag <> 'YV-8012' AND y.tag <> 'YV-8012')+ (b)
}
RETURN b.tag AS tag, true AS reachable

MATCH (a:PlantItem {tag: 'P-2001A'}), (b:PlantItem {tag: 'P-3901B'}), (v:Valve)
WHERE v <> a AND v <> b
  AND EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN count(DISTINCT v) AS valve_count, collect(DISTINCT v.tag) AS valve_tags

MATCH (s:PlantItem {tag: 'P-801B'}),
      (t:PlantItem {tag: 'P-3001C'}),
      (blocked:PlantItem {tag: 'P-2702A'})
RETURN s.tag AS source_tag,
       t.tag AS destination_tag,
       EXISTS {
         MATCH (s) ((x:PlantItem WHERE x <> blocked)-[:line_to]->(y:PlantItem WHERE y <> blocked))+ (t)
       } AS reachable_without_blocked
ORDER BY source_tag, destination_tag;

MATCH (a:PlantItem {tag: 'V-901'}), (b:PlantItem {tag: 'TK-4102'}), (y:PlantItem {tag: 'YV-28001'})
RETURN a.tag AS source, b.tag AS destination,
       EXISTS {
         MATCH (a) ((x)-[:line_to]->(z) WHERE x <> y AND z <> y)+ (b)
       } AS reachable_without_yv28001

MATCH (a:PlantItem {tag: 'E-3901'}), (b:PlantItem {tag: 'P-3401B'})
MATCH p = shortestPath((a)-[:line_to*]->(b))
RETURN [n IN nodes(p) | n.tag] AS tags;

MATCH (a:PlantItem {tag: 'T-2701'}), (b:PlantItem {tag: 'E-1602'})
MATCH p = shortestPath((a)-[:line_to*]->(b))
RETURN [n IN nodes(p) WHERE n.kind IN ['equipment', 'valve'] | n.tag] AS tags;

MATCH (v:Valve)
WHERE coalesce(v.operating_position, 'NO') = 'NO'
  AND EXISTS { (v)-[:line_to*1..]->(:PlantItem {tag: 'E-2102'}) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (e:PlantItem {tag: 'E-1603'}), (v:PlantItem:NeedleValve {line_number: '4-CD-160016-A1A-H'})
WHERE EXISTS { (e)-[:line_to*1..]->(v) }
RETURN v.tag AS tag, v.operating_position AS operating_position

MATCH (v:PlantItem:ButterflyValve {line_number: '6-P-290015-A1A-N'}), (h:PlantItem {tag: 'H-3001'})
WHERE EXISTS { (v)-[:line_to*1..]->(h) }
RETURN v.tag AS tag, coalesce(v.operating_position, 'NO') AS normal_position

MATCH (v:PlantItem:Valve)-[:line_to*1..]->(:PlantItem {tag: 'EJ-4001A'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (v:PlantItem:Valve)-[:line_to*1..]->(target:PlantItem {tag: 'V-1601'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;
